sys_ux_data_broker_transform.script:
function transform(input) {

    if (!input || !input.quizSessionId || !input.participantId || !input.buzzerTime) {
        return {
            success: false,
            message: "Missing required buzzer response input."
        };
    }

    // Get the Quiz Session
    var session = new GlideRecord("x_1892173_stopwa_0_quiz_session");

    if (!session.get(input.quizSessionId)) {
        return {
            success: false,
            message: "Quiz Session not found."
        };
    }

    // Get the server-side Run Start Time
    var runStartValue = session.getValue("run_start_time");

    if (!runStartValue) {
        return {
            success: false,
            message: "Run Start Time is empty."
        };
    }

    // Convert the server Run Start Time to GlideDateTime
    var runStart = new GlideDateTime(runStartValue);

    // Convert browser epoch milliseconds to GlideDateTime
    var buzzerEpoch = parseInt(input.buzzerTime, 10);

    if (isNaN(buzzerEpoch)) {
        return {
            success: false,
            message: "Invalid Buzzer Time."
        };
    }

    var buzzer = new GlideDateTime();
    buzzer.setNumericValue(buzzerEpoch);

    // Calculate response time in seconds
    var responseTime =
        (buzzer.getNumericValue() - runStart.getNumericValue()) / 1000;

    // Prevent negative response times
    if (responseTime < 0) {
        responseTime = 0;
    }

    // Create Buzzer Response
    var response = new GlideRecord(
        "x_1892173_stopwa_0_buzzer_response"
    );

    response.initialize();

    response.setValue(
        "quiz_session",
        input.quizSessionId
    );

    response.setValue(
        "participant",
        input.participantId
    );

    // Store the correctly converted Date/Time
    response.setValue(
        "buzzer_time",
        buzzer.getValue()
    );

    // Store response time in seconds with millisecond precision
    response.setValue(
        "response_time",
        responseTime.toFixed(3)
    );

    response.setValue(
        "run_number",
        parseInt(input.runNumber, 10) || 1
    );

    var sysId = response.insert();

    return {
        success: !!sysId,
        sys_id: sysId || "",
        buzzerTime: buzzer.getValue(),
        responseTime: responseTime.toFixed(3)
    };
}
